_ALL_COMPUTE_CELLS = []


class InputCell:
    def __init__(self, initial_value):
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        _propagate()


class ComputeCell:
    def __init__(self, inputs, compute_function):
        self._inputs = inputs
        self._compute_function = compute_function
        self._callbacks = []
        self._value = self._recompute()
        _ALL_COMPUTE_CELLS.append(self)

    @property
    def value(self):
        return self._value

    def _recompute(self):
        self._value = self._compute_function([cell.value for cell in self._inputs])

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)

    def _fire_callbacks(self):
        for callback in self._callbacks:
            callback(self._value)


def _propagate():
    """Recompute all compute cells in dependency order and fire callbacks
    for cells whose value changed from the previous stable state."""
    visited = set()
    order = []

    def visit(cell):
        if id(cell) in visited:
            return
        visited.add(id(cell))
        for dependency in cell._inputs:
            if isinstance(dependency, ComputeCell):
                visit(dependency)
        order.append(cell)

    for cell in _ALL_COMPUTE_CELLS:
        visit(cell)

    for cell in order:
        old_value = cell._value
        cell._recompute()
        if cell._value != old_value:
            cell._fire_callbacks()

